var ConsoleOutputStream = module.exports = function() {
    if (this instanceof ConsoleOutputStream) {
        this._hashCode = null;
    } else {
        return new ConsoleOutputStream();
    }
}

var consoleBuffer = "";

function flushConsoleBuffer() {
    if (consoleBuffer.length) {
      var temp = consoleBuffer;
      consoleBuffer = ""; 
        if(temp.indexOf("DeviceControl::setLights")>-1)
        {
            return;
        }
        console.info(temp); 
    }
  }
function print(ch) {
    if (ch === 10) {
      flushConsoleBuffer();
    } else {
      consoleBuffer += String.fromCharCode(ch);
    }
  };

ConsoleOutputStream.getClassName = function() {
    return "com/sun/cldchi/io/ConsoleOutputStream";
}
 
ConsoleOutputStream.write = function(ch) { 
    print(ch);
}
